ALTER TABLE public.loan_applications ADD CONSTRAINT loan_amount_positive CHECK (amount > 0); ALTER TABLE public.loan_applications ADD CONSTRAINT loan_tenure_positive CHECK (tenure_months > 0); ALTER TABLE public.loan_applications ADD CONSTRAINT loan_status_valid CHECK (status IN ('pending','approved','rejected','completed')); ALTER TABLE public.transactions ADD CONSTRAINT transaction_amount_positive CHECK (amount > 0); ALTER TABLE public.transactions ADD CONSTRAINT transaction_type_valid CHECK (type IN ('deposit','withdraw','disbursement')); ALTER TABLE public.transactions ADD CONSTRAINT transaction_status_valid CHECK (status IN ('pending','completed','failed')); CREATE UNIQUE INDEX transactions_one_disbursement_per_loan ON public.transactions (loan_id) WHERE type = 'disbursement' AND status = 'completed';